    /// comment already said. What it is, measured in «koliseo completo con invitacion-koli 2vs2»:
    /// the client sends it only once, with «1001» -- f2=1 --, and that capture is of a TWO versus
    /// two. Index 1 of the ltd is exactly the two-player teams entry, so the field is the
    /// mode and it fits without forcing anything.
    /// </remarks>
    public const string Luy = "luy";
    // The answer is the lth and not the lsx: see that one's note.

    /// <summary>That is the whole actor listing; empty, right behind jss. Without it, the client never considers the map loaded, waits about two seconds and retries with knm, kno and kny.</summary>
    public const string Lva = "lva";

    /// <summary>Unidentified. 2 uses in the emulator.</summary>
    public const string Lwb = "lwb";

    /// <summary>Elegir un ornamento; un mensaje vacio significa ninguno.</summary>
    public const string Lwm = "lwm";

    /// <summary>Acknowledgement of receipt.</summary>
    public const string Lwx = "lwx";

    /// <summary>The slot the server chose.</summary>
    public const string Lwz = "lwz";

    /// <summary>Acknowledgement of receipt.</summary>
    public const string Lxa = "lxa";

    /// <summary>Your look has changed: the panel's preview, which nobody else sees. f1 is a uuid constant within the session and different per character; where the client learns it has not been found.</summary>
    public const string Lxc = "lxc";

    /// <summary>Unidentified. 3 uses in the emulator.</summary>
    public const string Lxd = "lxd";

    /// <summary>Showing or hiding what is in a slot; with f3 set that skin disappears from the next lxc, the garment is not taken off, it stops being drawn.</summary>
    public const string Lxg = "lxg";

    /// <summary>Acknowledgement of receipt.</summary>
    public const string Lxk = "lxk";

    /// <summary>The window's state; f7 is the same uuid the lxc preview carries and f12 its same look, which is how the panel knows the answer is its own.</summary>
    public const string Lxo = "lxo";

    /// <summary>Save: here the draft becomes what is worn and the look reaches the rest of the map. The mappings file calls it AlignmentSubAreaUpdate, and that is false.</summary>
    public const string Lxs = "lxs";

    /// <summary>The aura.</summary>
    public const string Lxw = "lxw";

    /// <summary>Putting in or emptying a specific slot; without a variant, and without an item it empties the slot.</summary>
    public const string Lyf = "lyf";

    /// <summary>Acknowledgement of receipt.</summary>
    public const string Lyj = "lyj";

    /// <summary>It carries the aura in the appearance flow (f1: aura id, empty if none); in every equip and unequip capture it carries the constant 206, whose meaning is not established.</summary>
    public const string Lym = "lym";

    /// <summary>Putting on a garment letting the server choose the slot; it accepts a variant, which is what living items use to imitate one garment or another.</summary>
    public const string Lys = "lys";

    /// <summary>The wardrobe's stored outfits; mandatory, without it the cosmetics window makes its sound and is not drawn, dying in CosmeticUi.DisplayOutfit. In the replay it is replaced by those of the character playing.</summary>
    public const string Lyt = "lyt";

    /// <summary>Guardado confirmado.</summary>
    public const string Lyu = "lyu";

    /// <summary>Acknowledgement of receipt.</summary>
    public const string Lyv = "lyv";

    /// <summary>Choosing a title; it only touches the draft. An empty message means none.</summary>
    public const string Lze = "lze";

    /// <summary>Unidentified. 1 use in the emulator.</summary>
    public const string Mes = "mes";

    /// <summary>Unidentified. 1 use in the emulator.</summary>
    public const string Mez = "mez";

    /// <summary>Unidentified. 1 use in the emulator.</summary>
    public const string Mfa = "mfa";

    /// <summary>Unidentified. 1 use in the emulator.</summary>
    public const string Mgq = "mgq";

    /// <summary>Unidentified. 1 use in the emulator.</summary>
    public const string Mgt = "mgt";

    /// <summary>Content catalogue identifier; opaque, the client only compares it with itself.</summary>
    public const string Mgz = "mgz";

    /// <summary>
    /// The real name of the message travelling with this opcode. 0 of 253
    /// are known; for the rest it returns an empty string, which is the honest thing.
    /// </summary>
    public static string Label(string opcode) => Labels.GetValueOrDefault(opcode, "");

    /// <summary>The known ones, by opcode.</summary>
    public static readonly IReadOnlyDictionary<string, string> Labels =
        new Dictionary<string, string>(StringComparer.Ordinal)
        {
        };
}
